"""Undo, redo and history (docs/undo.md)."""

from binkeep import journal
from binkeep.bins import normalize
from binkeep.errors import DataError, Refused


def stacks(entries):
    """Reads the journal; returns (done, undone, dropped, undo_lines) with entries in the stacks."""
    done, undone, dropped, undo_line = [], [], [], {}
    for e in entries:
        op = e["op"]
        if op in journal.OPS:
            done.append(e)
            dropped.extend(undone)
            undone.clear()
        elif op in ("undo", "redo"):
            src, dst = (done, undone) if op == "undo" else (undone, done)
            if not src or e.get("target") != src[-1]["seq"] or e.get("target") is None:
                raise DataError("journal", f"line {e['seq']}: {op} does not match the stacks")
            dst.append(src.pop())
            if op == "undo":
                undo_line[e["target"]] = e
        # other ops are ignored
    return done, undone, dropped, undo_line


def _units(ctx, e):
    return e["qty"] * ctx.items[e["sku"]].pack_size if e.get("uom") == "pk" else e["qty"]


def _format1_changes(ctx, e, store):
    """[(bin, new quantity)] taking the format 1 operation back, in order."""
    sku, op = e["sku"], e["op"]
    cur, out = {}, []

    def q(code):
        return cur.get(code, store.qty(sku, code))

    def put(code, v):
        cur[code] = v
        out.append((code, v))

    try:
        if op == "receive":
            c = normalize(e["bin"])
            put(c, q(c) - _units(ctx, e))
        elif op == "issue":
            for b, n in reversed(e["picks"]):
                c = normalize(b)
                put(c, q(c) + n)
        elif op == "move":
            t, f = normalize(e["to"]), normalize(e["from"])
            put(t, q(t) - e["qty"])
            put(f, q(f) + e["qty"])
    except (KeyError, TypeError, ValueError):
        raise DataError("journal", f"line {e['seq']}: cannot be read") from None
    return out


def _apply(ctx, store, sku, targets):
    effects = []
    for code, v in targets:
        if code not in ctx.bins:
            raise Refused("unknown-bin", f"no bin {code}")
        before = store.qty(sku, code)
        store.set(sku, code, v, force=True)
        effects.append({"bin": code, "before": before, "after": v})
    return effects


def _targets(e):
    try:
        return [(normalize(x["bin"]), x["before"]) for x in reversed(e["effects"])]
    except (KeyError, TypeError):
        raise DataError("journal", f"line {e['seq']}: bad effects") from None


def run(ctx, kind, steps):
    store = ctx.store
    entries = list(ctx.entries)
    new = []
    for _ in range(steps):
        done, undone, _d, undo_line = stacks(entries)
        if kind == "undo":
            if not done:
                raise Refused("nothing-to-undo", "nothing to undo")
            op = done[-1]
            if op["op"] == "fix":
                raise Refused("barrier", "a fix cannot be undone")
            if op["op"] == "count" and op.get("v") != 2:
                raise Refused("irreversible", "format 1 count cannot be undone")
            if op.get("v") == 2:
                targets = _targets(op)
            else:
                targets = _format1_changes(ctx, op, store)
        else:
            if not undone:
                raise Refused("nothing-to-redo", "nothing to redo")
            op = undone[-1]
            targets = _targets(undo_line[op["seq"]])
        store = store.copy()
        effects = _apply(ctx, store, op["sku"], targets)
        line = journal.entry(journal.next_seq(entries), kind, ctx.by, op["sku"],
                             target=op["seq"], effects=effects)
        entries.append(line)
        new.append((line, op))
    return store, new


def history(ctx, limit):
    done, undone, dropped, _ = stacks(ctx.entries)
    status = {}
    for e in done:
        status[e["seq"]] = "barrier" if e["op"] == "fix" else "done"
    for e in undone:
        status[e["seq"]] = "undone"
    for e in dropped:
        status[e["seq"]] = "dropped"
    ops = [e for e in ctx.entries if e["op"] in journal.OPS]
    return [f"{e['seq']:>5}  {e['op']:<7}  {e.get('sku', ''):<10}  {status[e['seq']]}"
            for e in reversed(ops[-limit:])]
